"use client";
import React from "react";
import { captureReactRenderError } from "../../host/diagnostics.js";
class ToolRendererErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError() {
    return { hasError: true };
  }
  componentDidCatch(error, errorInfo) {
    console.error(
      `[ToolRendererErrorBoundary] DB renderer for "${this.props.toolName}" threw at render:`,
      error,
      errorInfo.componentStack
    );
    captureReactRenderError(error, {
      boundary: "ToolRendererErrorBoundary",
      componentStack: errorInfo.componentStack ?? null,
      relation: `tool:${this.props.toolName}`
    });
  }
  render() {
    if (this.state.hasError) return this.props.fallback;
    return this.props.children;
  }
}
export {
  ToolRendererErrorBoundary
};
